import{_ as l,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Developer Monthly 2020-07-02","description":"","frontmatter":{"title":"Ceph Developer Monthly 2020-07-02","date":"2020-07-02T00:00:00.000Z","updated":"2020-07-02T00:00:00.000Z","tags":["Ceph","distributed storage","Crimson OST","containerization","testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Developer_Monthly_2020-07-02.md","filePath":"posts/2020/Ceph_Developer_Monthly_2020-07-02.md","lastUpdated":1780459816000}'),o={name:"posts/2020/Ceph_Developer_Monthly_2020-07-02.md"};function r(n,e,s,p,h,d){return i(),t("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>会议主题：Ceph Bridge July 2020 更新 参会人员：Ceph 开发团队成员 会议时间：2020年7月</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph 近期进展概述</strong></p><ul><li>已完成第一轮 portal 问题添加，包括基础设施和接口，用于 DNS 设备，并抽象化了顺序写入过程和事务结构。</li><li>实现了 B-tree 映射逻辑地址和统计地址，详细信息可在 Ceph 的 rst 文档中查看。</li><li>正在进行恢复和回填工作，目标是达到基本支持水平。</li></ul></li><li><p><strong>Crimson OST 集成</strong></p><ul><li>将 Crimson OST 集成到 Ceph 中，使用外部线程池和消息传递系统，已合并并可进行基准测试。</li><li>讨论了 Crimson 存储的当前限制，包括缺少垃圾回收和脏节点写入功能。</li></ul></li><li><p><strong>容器化部署</strong></p><ul><li>准备容器镜像，以便在 Docker 中运行 Crimson，已解决 Crimson 和 Seastar 名称不同的问题。</li></ul></li><li><p><strong>测试和功能完善</strong></p><ul><li>讨论了 Crimson 存储的当前限制，包括缺少垃圾回收和脏节点写入功能。</li><li>强调了恢复和回填测试的重要性，以及如何通过随机化测试来发现潜在的 bug。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>继续完善 Crimson OST 的功能，特别是恢复和回填功能。</li><li>完成容器镜像的准备，并确保 Ceph 部署工具能够支持新的容器化部署方式。</li><li>增加更多的测试，特别是针对恢复和回填的随机化测试，以确保系统的稳定性和可靠性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续推进 Crimson OST 的集成和功能完善。</li><li>完成容器镜像的准备，并更新相关工具以支持新的部署方式。</li><li>增加针对恢复和回填的随机化测试，以确保系统的稳定性和可靠性。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>完成 Crimson OST 的恢复和回填功能的开发。</li><li>更新容器镜像和相关工具，确保能够支持新的部署方式。</li><li>增加更多的测试，特别是针对恢复和回填的随机化测试，以发现和修复潜在的 bug。</li></ul>',9)])])}const c=l(o,[["render",r]]);export{_ as __pageData,c as default};
